1	import 'dart:async';
2	
3	import 'package:flutter_test/flutter_test.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	import 'package:cerne/core/failure/failure.dart';
7	import 'package:cerne/features/account/domain/repositories/account_settings_repository.dart';
8	import 'package:cerne/features/account/presentation/cubit/account_settings_cubit.dart';
9	
10	/// A plain (non-mocktail) fake — same rationale as `vault_lock_screen_test.
11	/// dart`'s own `_FakeVaultRepository`: this suite needs a scriptable
12	/// `setBiometricEnabled()` result plus a real stream the cubit actually
13	/// subscribes to, which a mocktail stub can't give as naturally.
14	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
15	  bool _value = true;
16	  final _controller = StreamController<bool>.broadcast();
17	
18	  /// The next `setBiometricEnabled()` call's own result — defaults to a
19	  /// failure so a test must opt in to the success path explicitly.
20	  Either<Failure, Unit> setBiometricEnabledResult = left(
21	    const Failure.malformedResponse(message: 'fake: not configured'),
22	  );
23	
24	  int setBiometricEnabledCallCount = 0;
25	
26	  // spec-8-3 — a scriptable profile-name slice, same rationale
27	  // [setBiometricEnabledResult] already gives for the toggle: a test must
28	  // opt in to a non-default [currentDisplayName]/[currentEmail] or a
29	  // [setDisplayNameResult] success explicitly.
30	  @override
31	  String currentDisplayName = '';
32	  @override
33	  String currentEmail = '';
34	  Either<Failure, Unit> setDisplayNameResult = left(
35	    const Failure.malformedResponse(message: 'fake: not configured'),
36	  );
37	  int setDisplayNameCallCount = 0;
38	  String? lastSetDisplayNameArg;
39	
40	  /// Lets a test hold `setDisplayName()` unresolved, to observe
41	  /// `state.isSavingName` mid-flight — same rationale
42	  /// `account_settings_screen_test.dart`'s own `setBiometricEnabledGate`
43	  /// already gives for the toggle.
44	  Completer<void>? setDisplayNameGate;
45	
46	  /// Review finding — mirrors `AccountSettingsRepositoryImpl.
47	  /// setDisplayName`'s own "echo wins" behavior: on success,
48	  /// `currentDisplayName` is set to this value (defaulting to whatever was
49	  /// actually sent) rather than always just echoing the argument back
50	  /// unchanged. Lets a test prove the cubit reads the repository's own
51	  /// post-save value rather than assuming the server stored exactly what
52	  /// was sent.
53	  String? setDisplayNameEchoedNameOverride;
54	
55	  @override
56	  Future<Either<Failure, Unit>> setDisplayName(String name) async {
57	    setDisplayNameCallCount += 1;
58	    lastSetDisplayNameArg = name;
59	    final gate = setDisplayNameGate;
60	    if (gate != null) {
61	      await gate.future;
62	    }
63	    if (setDisplayNameResult.isRight()) {
64	      currentDisplayName = setDisplayNameEchoedNameOverride ?? name;
65	    }
66	    return setDisplayNameResult;
67	  }
68	
69	  @override
70	  bool get currentBiometricEnabled => _value;
71	
72	  @override
73	  Stream<bool> get biometricEnabledStream {
74	    return Stream<bool>.multi((controller) {
75	      controller.add(_value);
76	      final subscription = _controller.stream.listen(
77	        controller.add,
78	        onError: controller.addError,
79	        onDone: controller.close,
80	      );
81	      controller.onCancel = subscription.cancel;
82	    }, isBroadcast: true);
83	  }
84	
85	  @override
86	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
87	
88	  @override
89	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
90	    setBiometricEnabledCallCount += 1;
91	    final previous = _value;
92	    _emit(enabled);
93	    final result = setBiometricEnabledResult;
94	    if (result.isLeft()) {
95	      _emit(previous);
96	    }
97	    return result;
98	  }
99	
100	  @override
101	  Future<void> dispose() => _controller.close();
102	
103	  void _emit(bool value) {
104	    _value = value;
105	    _controller.add(value);
106	  }
107	}
