109	Future<List<AccountSettingsState>> _emittedDuring(
110	  AccountSettingsCubit cubit,
111	  Future<void> Function() act,
112	) async {
113	  final emitted = <AccountSettingsState>[];
114	  final subscription = cubit.stream.listen(emitted.add);
115	  await act();
116	  // `pumpEventQueue()` (not a single `Future.delayed(Duration.zero)`): the
117	  // `biometricEnabled` mirror travels repository -> Stream.multi's own
118	  // forwarding subscription -> cubit's `emit()` -> `_stateController`,
119	  // several microtask hops deep — one `Duration.zero` delay only guarantees
120	  // draining one hop, leaving a later hop's delivery to land after this
121	  // helper already returned.
122	  await pumpEventQueue();
123	  await subscription.cancel();
124	  return emitted;
125	}
