236	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
237	/// pair and pumps the real screen around it, registering both for cleanup.
238	///
239	/// Deliberately constructed *inside* each `testWidgets` body (via this
240	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
241	/// `package:test`'s own per-test zone, a different zone than the one
242	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
243	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
244	/// subscription to the repository's stream, set up in its constructor)
245	/// created in that outer zone does not reliably get its pending events
246	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
247	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
248	/// widget never rebuilt, no matter how many `pump()` calls followed.
249	/// Constructing the cubit here, inside the same zone `tester.pump()`
250	/// drains, avoids the mismatch entirely.
251	Future<(_FakeAccountSettingsRepository, AccountSettingsCubit)> _pumpScreen(
252	  WidgetTester tester,
253	) async {
254	  final fakeRepository = _FakeAccountSettingsRepository();
255	  final cubit = AccountSettingsCubit(fakeRepository);
256	  addTearDown(() => cubit.close());
257	  addTearDown(fakeRepository.dispose);
258	
259	  final router = _routerWith(
260	    AccountSettingsScreen(
261	      cubit: cubit,
262	      dashboardCubit: _buildDashboardCubit(),
263	      narrativeCubit: _buildNarrativeCubit(),
264	    ),
265	  );
266	  addTearDown(router.dispose);
267	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
268	
269	  return (fakeRepository, cubit);
270	}
