      throw UnimplementedError('not expected to be called');

  @override
  void markAuthenticated() =>
      throw UnimplementedError('not expected to be called');

  @override
  Future<Either<Failure, Unit>> logout() async {
    logoutCallCount += 1;
    final gate = logoutGate;
    if (gate != null) {
      await gate.future;
    }
    return logoutResult;
  }

  @override
  Future<void> dispose() async {}
}

